theorem RISData.vector_norm_le_one {D : ConstructionData 𝕜} {N : ℕ} {ε : ℝ}
    {x : Fin N → C00 𝕜} (h : RISData D ε x) (i : Fin N) : implicitNorm D (x i) ≤ 1 :=
  (implicitNorm_le_intervalNorm D (h.size_pos i) (x i)).trans (h.norm_bound i)

